/** A linear run of detailed graph rows. */
export type DetailedGraphLinearSegment = {
  /** The reference row that starts this run, if any. */
  referenceIdx: number | null;
  /** The row indices in this run. */
  rowIdxs: Array<number>;
};

/** A reference row in a detailed graph workspace. */
export type DetailedGraphReference = {
  /** The reference name rendered in this row. */
  refName: DetailedGraphReferenceName;
  /** Derived status for this reference, when available. */
  status: DetailedGraphReferenceStatus | null;
};

/** A Git reference name with both byte-preserving and frontend-friendly forms. */
export type DetailedGraphReferenceName = {
  /** The full ref name bytes, such as `refs/heads/feature`. */
  fullNameBytes: Array<number>;
  /** The full ref name as a string, such as `refs/heads/feature`. */
  fullName: string;
  /** The shortened display name, such as `feature`. */
  displayName: string;
};

/** A reference and the rows reachable from it down to the next reference. */
export type DetailedGraphReferenceSegment = {
  /** The reference row index. */
  referenceIdx: number;
  /** The row indices in this reference segment. */
  rowIdxs: Array<number>;
};

/** Derived status for a detailed graph reference row. */
export type DetailedGraphReferenceStatus = {
  /** The remote-tracking reference this reference was compared with. */
  remoteRef: DetailedGraphReferenceName | null;
  /** Push status for this reference. */
  pushStatus: PushStatus;
  /** Push status including parent references below it in the stack. */
  combinedPushStatus: PushStatus;
};

/** One row in a rendered detailed graph stack. */
export type DetailedGraphRow = {
  /** The commit or reference represented by this row. */
  data: DetailedGraphRowData;
  /** The node columns for this row. */
  nodeLine: Array<NodeLine>;
  /** The link columns for this row, if a link row is necessary. */
  linkLine: Array<LinkLine> | null;
  /** The location of terminators, if a terminator row is necessary. */
  termLine: Array<boolean> | null;
  /** The pad columns for this row. */
  padLines: Array<PadLine>;
};

/** The typed data represented by one detailed graph row. */
export type DetailedGraphRowData = {
  type: "Commit";
  subject: Commit;
} | {
  type: "Reference";
  subject: DetailedGraphReference;
};

/** One rendered stack in a detailed graph workspace. */
export type DetailedGraphStack = {
  /** The rendered rows in this stack. */
  rows: Array<DetailedGraphRow>;
  /** Linear row runs split by reference rows and graph forks/merges. */
  linearSegments: Array<DetailedGraphLinearSegment>;
  /**
   * Per-reference row runs, including shared commits for every reference
   * that reaches them.
   */
  referenceSegments: Array<DetailedGraphReferenceSegment>;
};

/** The rendered detailed graph workspace. */
export type DetailedGraphWorkspace = {
  /** The rendered stacks in the workspace. */
  stacks: Array<DetailedGraphStack>;
};

/** A comment anchored to a line in a diff, as returned to every consumer. */
export type DiffComment = {
  /** The unique identifier of the comment. */
  id: string;
  /** The worktree-relative path of the file the comment is anchored to. */
  path: string;
  /**
   * `None` when the comment is anchored to the uncommitted worktree diff, or the change-id of
   * the commit whose first-parent diff the comment is anchored to.
   */
  commitChangeId: string | null;
  /** The side of the diff the anchored line lives on. */
  side: DiffSide;
  /** The 1-based line number of the anchored line, in `side`'s coordinates. */
  lineNumber: number;
  /** The content of the anchored line (without the leading `+`/`-`/space diff marker). */
  lineContent: string;
  /** The comment text itself. */
  payload: string;
  /** When the comment was created, in milliseconds since the Unix epoch (UTC). */
  createdAtMs: number;
  /** When the comment payload was last updated, in milliseconds since the Unix epoch (UTC). */
  updatedAtMs: number;
  /**
   * A unified-diff-formatted excerpt of the current diff around the anchored line, so consumers
   * can understand what the comment is about without recomputing the diff.
   * Only present on comments returned from [`list_comments`].
   */
  context: string | null;
};

/** A hunk as used in a [UnifiedPatch], which also contains all added and removed lines. */
export type DiffHunk = {
  /** The 1-based line number at which the previous version of the file started. */
  oldStart: number;
  /** The non-zero amount of lines included in the previous version of the file. */
  oldLines: number;
  /** The 1-based line number at which the new version of the file started. */
  newStart: number;
  /** The non-zero amount of lines included in the new version of the file. */
  newLines: number;
  /**
   * A unified-diff formatted patch like:
   *
   * ```diff
   * @@ -1,6 +1,8 @@
   * This is the first line of the original text.
   * -Line to be removed.
   * +Line that has been replaced.
   *  This is another line in the file.
   * +This is a new line added at the end.
   * ```
   *
   * The line separator is the one used in the original file and may be `LF` or `CRLF`.
   * Note that the file-portion of the header isn't used here.
   *
   * Also note that this has possibly been decoded lossily, assuming UTF8 if the encoding couldn't be determined,
   * replacing invalid codepoints with markers.
   */
  diff: string;
};

/**
 * The side of a diff a comment line lives on: `old` line numbers count in the pre-image,
 * `new` line numbers in the post-image. Context lines exist on both sides.
 */
export type DiffSide = "old" | "new";

/** A change that should be used to create a new commit or alter an existing one, along with enough information to know where to find it. */
export type DiffSpec = {
  /** The previous location of the entry, the source of a rename if there was one. */
  previousPathBytes: Array<number> | null;
  /**
   * The worktree-relative path to the worktree file with the content to commit.
   *
   * If `hunks` is empty, this means the current content of the file should be committed.
   */
  pathBytes: Array<number>;
  /**
   * If one or more hunks are specified, match them with actual changes currently in the worktree.
   * Failure to match them will lead to the change being dropped.
   * If empty, the whole file is taken as is if this seems to be an addition.
   * Otherwise, the whole file is being deleted.
   */
  hunkHeaders: Array<HunkHeader>;
};

/** Holds relevant state required to switch to and from edit mode */
export type EditModeMetadata = {
  /** The sha of the commit getting edited. */
  commitOid: string;
  /** The ref of the vbranch which owns this commit. */
  stackId: string;
};

export type EntryKind = "Tree" | "Blob" | "BlobExecutable" | "Link" | "Commit";

/** Whether installation may replace an existing symlink to another executable. */
export type ExistingSymlinkPolicy = "Refuse" | "Replace";

export type ExtraCsp = {
  /** Additional hosts that the application can connect to. */
  hosts: Array<string>;
  /** Additional hosts for img-src that the application can load images from. */
  imgSrc: Array<string>;
};

export type FeatureFlags = {
  /**
   * Control how the filesystem watch should be established.
   * Possible values: "auto", "legacy", "modern".
   * "auto" automatically picks based on platform heuristics (default).
   * "legacy" uses recursive watching.
   * "modern" uses ignore-aware non-recursive watching.
   */
  watchMode: string;
  /** Experimental. */
  writeCommitEvolution: boolean;
  /** Show the experimental file browser in the TUI. */
  tuiFileBrowser: boolean;
  /**
   * Open the experimental native client (GPUI) instead of the web app when GitButler
   * starts, on macOS builds that include it.
   */
  gpui: boolean;
};

/** Update request for [`crate::app_settings::FeatureFlags`]. */
export type FeatureFlagsUpdate = {
  gpui?: boolean | null;
};

export type Fetch = {
  /** The frequency at which the app will automatically fetch. A negative value (e.g. -1) disables auto fetching. */
  autoFetchIntervalMinutes: number;
};

/** Update request for [`crate::app_settings::Fetch`]. */
export type FetchUpdate = {
  autoFetchIntervalMinutes?: number | null;
};

/** File contents and metadata suitable for display in a frontend. */
export type FileInfo = {
  /** File content, base64 encoded when `mime_type` is present. */
  content: string | null;
  /** The basename derived from the relative path. */
  fileName: string;
  /** The decoded content size in bytes. */
  size: number | null;
  /** The inferred MIME type for binary displayable content. */
  mimeType: string | null;
};

export type ForgeCapabilities = {
  checks: boolean;
  repoInfo: boolean;
  prService: boolean;
  listService: boolean;
  /** Conversation comments and review submissions can be read and written. */
  reviewComments: boolean;
  /** Labels and review requests can be listed and changed. */
  reviewManagement: boolean;
};

/**
 * Per-forge display + URL config delivered to the frontend so it
 * doesn't need to branch on forge name. Computed from the project's
 * own remote URL plus a forge-name lookup for the rest.
 */
export type ForgeInfo = {
  name: ForgeName;
  /**
   * Already SSH→HTTPS converted and includes Azure's organization
   * segment when applicable. Append the *Path values below to build
   * the various web URLs.
   */
  baseUrl: string;
  /** Format: `{baseUrl}{commitUrlPath}{commitId}`. */
  commitUrlPath: string;
  /** Format: `{baseUrl}{prUrlPath}{number}`. */
  prUrlPath: string;
  /** Display labels for PR/MR. */
  unit: ForgeUnitInfo;
  /** PostHog event prefix ("PR Successful", "Gitlab MR Successful"). */
  posthogLabel: string;
  /** Which Rust-backed services the forge supports today. */
  capabilities: ForgeCapabilities;
};

/** Supported git forge types */
export type ForgeName = "github" | "gitlab" | "bitbucket" | "azure";

/**
 * Represents a review (pull request/merge request) from a forge platform (GitHub, GitLab, etc.).
 *
 * Contains metadata and state information about a code review, including its location,
 * participants, labels, and timestamps for various lifecycle events.
 */
export type ForgeReview = {
  /** The URL to view this review in a web browser */
  htmlUrl: string;
  /**
   * The unique identifier number for this review within its repository.
   * This can be a PR or MR number.
   */
  number: number;
  /** The title/summary of the review */
  title: string;
  /** The detailed description or body text of the review, if provided. */
  body: string | null;
  /** The user who created this review. */
  author: ForgeReviewUser | null;
  /** Labels or tags applied to categorize this review. */
  labels: Array<ForgeReviewLabel>;
  /** Whether this review is in draft state (not ready for final review). */
  draft: boolean;
  /**
   * The name of the branch containing the proposed changes.
   * This is the short name of the branch (e.g., "feature-branch")
   */
  sourceBranch: string;
  /**
   * The name of the branch that will receive the changes when merged.
   * This is the short name of the branch (e.g., "main" or "develop")
   */
  targetBranch: string;
  /** The git commit SHA that this review is based on. */
  sha: string;
  /** Commits on the target branch that represent this review having landed. */
  integrationCommitShas: Array<string>;
  /** ISO 8601 timestamp of when the review was created. */
  createdAt: string | null;
  /** ISO 8601 timestamp of when the review was last modified. */
  modifiedAt: string | null;
  /** ISO 8601 timestamp of when the review was merged, if applicable. */
  mergedAt: string | null;
  /** ISO 8601 timestamp of when the review was closed, if applicable. */
  closedAt: string | null;
  /** SSH URL for cloning the repository containing this review. */
  repositorySshUrl: string | null;
  /** HTTPS URL for cloning the repository containing this review. */
  repositoryHttpsUrl: string | null;
  /**
   * The owner (user or organization) of the repository from which the branch originates.
   * In the case of a fork, this will be the fork owner's username.
   */
  repoOwner: string | null;
  /** Whether the source/head repository for this review is a fork. */
  headRepoIsFork: boolean;
  /** Users who have been requested to review or have reviewed this code. */
  reviewers: Array<ForgeReviewUser>;
  /** Whether auto-merge (merge once the forge's requirements pass) is enabled. */
  autoMergeEnabled: boolean;
  /** The platform-specific symbol for this review type (e.g., "#" for GitHub pull requests and "!" for MRs). */
  unitSymbol: string;
  /** The timestamp when this review was last fetched from the forge. */
  lastSyncAt: string;
};

/**
 * A top-level comment on a review's conversation thread. Fetched fresh
 * from the forge; not cached. Diff-anchored review comments are not
 * part of this type.
 */
export type ForgeReviewComment = {
  /** Forge-assigned identifier of the comment. */
  id: number;
  /** The comment text, as forge-flavored markdown. */
  body: string;
  /** The comment's author. */
  author: ForgeReviewUser | null;
  /** ISO 8601 timestamp of when the comment was created. */
  createdAt: string | null;
  /** ISO 8601 timestamp of the comment's last edit. */
  modifiedAt: string | null;
  /** The URL to view this comment in a web browser. */
  htmlUrl: string;
  /** Reaction tallies on this comment, nonzero kinds only. */
  reactions: Array<ForgeReviewReactionCount>;
};

export type ForgeReviewLabel = {
  name: string;
  description: string | null;
  color: string | null;
};

/**
 * One individual reaction, with who left it and the forge id that
 * addresses its removal. `kind` is the forge's native reaction name — an
 * open set; unknown kinds pass through rather than being dropped.
 * Fetched fresh; not cached.
 */
export type ForgeReviewReaction = {
  id: number;
  kind: string;
  user: ForgeReviewUser | null;
};

/**
 * One reaction kind's tally. `kind` is the forge's native reaction name
 * (GitHub: `+1`, `laugh`, …) — an open set, since forges like GitLab
 * allow arbitrary award emoji.
 */
export type ForgeReviewReactionCount = {
  kind: string;
  count: number;
};

/**
 * A submitted review (approval, change request, or review comment) on a
 * review. Fetched fresh from the forge; not cached. The caller's own
 * unsubmitted (pending) drafts are excluded.
 */
export type ForgeReviewSubmission = {
  /** Forge-assigned identifier of the submission. */
  id: number;
  /** Who submitted the review. */
  author: ForgeReviewUser | null;
  /** The verdict of this submission. */
  state: ForgeReviewSubmissionState;
  /** The summary text accompanying the submission, if any. */
  body: string | null;
  /** ISO 8601 timestamp of when the review was submitted. */
  submittedAt: string | null;
  /** The URL to view this submission in a web browser. */
  htmlUrl: string;
  /** The reactions left on the submission, with who left each. */
  reactions: Array<ForgeReviewReaction>;
};

/** The verdict a submitted review carries. */
export type ForgeReviewSubmissionState = "approved" | "changesRequested" | "commented" | "dismissed";

/**
 * A diff-anchored conversation on a review: where in the diff it hangs,
 * whether it has been resolved, and the comments left in it. Fetched
 * fresh from the forge; not cached.
 */
export type ForgeReviewThread = {
  /** The forge's thread identifier, opaque and only meaningful to it. */
  id: string;
  /** Path the thread hangs on, as the forge spells it. */
  path: string;
  /** The line in the current diff, or `None` once the thread is outdated. */
  line: number | null;
  /** First line of a multi-line thread; equals `line` for a single one. */
  startLine: number | null;
  /** Where the thread was left, which survives the diff moving on. */
  originalLine: number | null;
  side: ForgeReviewThreadSide;
  /** Whether someone marked the conversation done. */
  isResolved: boolean;
  /** Whether the diff the thread was left on has since changed. */
  isOutdated: boolean;
  comments: Array<ForgeReviewThreadComment>;
};

/** One comment inside a review thread. */
export type ForgeReviewThreadComment = {
  /** Forge-assigned identifier of the comment. */
  id: number;
  /** The comment text, as forge-flavored markdown. */
  body: string;
  author: ForgeReviewUser | null;
  /** ISO 8601 timestamp of when the comment was created. */
  createdAt: string | null;
  /** ISO 8601 timestamp of the comment's last edit. */
  modifiedAt: string | null;
  /** The URL to view this comment in a web browser. */
  htmlUrl: string;
  /** The diff the comment was anchored to, as a unified hunk. */
  diffHunk: string | null;
  /**
   * The review submission this comment was posted under, which is what
   * files it under a verdict rather than standing on its own.
   */
  reviewId: number | null;
};

/**
 * Which side of the diff a thread hangs on: `old` line numbers count in
 * the pre-image, `new` in the post-image. Same axis as a local diff
 * comment, so both can be anchored the same way.
 */
export type ForgeReviewThreadSide = "old" | "new";

export type ForgeReviewUpdate = {
  /** The unique identifier number for this review within its repository. This can be a PR or MR number. */
  number: number;
  /** The current body/description of the review, which may be None if no description is set. */
  body: string | null;
  /**
   * Whether the description should be synchronized. If false, the current description is
   * fetched from the forge before applying the configured stacking policy.
   */
  updateDescription?: boolean;
  /** The platform-specific symbol for this review type (e.g., "#" for GitHub pull requests and "!" for MRs). */
  unitSymbol: string;
  /** If set, update the base/target branch of this review to the given value. */
  targetBranch: string | null;
};

/**
 * Represents a user from a forge platform (e.g., GitHub, GitLab).
 *
 * This structure contains information about a user account on a forge platform,
 * including their identification details and profile information.
 */
export type ForgeReviewUser = {
  /** The unique numeric identifier for the user on the forge platform */
  id: number;
  /** The user's login username */
  login: string;
  /** The user's display name, if available */
  name: string | null;
  /** The user's email address, if publicly available */
  email: string | null;
  /** URL to the user's profile avatar image, if available */
  avatarUrl: string | null;
  /** Indicates whether this account is a bot account */
  isBot: boolean;
};

export type ForgeUnitInfo = {
  name: string;
  abbr: string;
  symbol: string;
};

export type ForgeUser = {
  provider: "github";
  details: GithubAccountIdentifier;
} | {
  provider: "gitlab";
  details: GitlabAccountIdentifier;
} | {
  provider: "bitbucket";
  details: BitbucketAccountIdentifier;
};

/**
 * A full reference name accepted as raw bytes.
 *
 * Use this as parameter transport when callers must avoid lossy UTF-8
 * conversion at the API boundary.
 */
export type FullNameBytes = Array<number>;

/** The full name of a Git reference. */
export type FullRefName = {
  /**
   * The full name, like `refs/heads/main` or `refs/remotes/origin/foo`.
   * Note that it might be degenerated if it can't be represented in Unicode.
   */
  full: string;
};

/** See [`GitConfigSettings`](crate::GitConfigSettings) for the docs. */
export type GitConfigSettings = {
  signCommits: boolean | null;
  gitbutlerGerritMode: boolean | null;
  gitbutlerReviewStackingDescription: ReviewStackingDescription | null;
  gitbutlerGithubStackingMode: GitHubStackingMode | null;
  gitbutlerForgeReviewTemplatePath: string | null;
  gitbutlerGitlabProjectId: string | null;
  gitbutlerGitlabUpstreamProjectId: string | null;
  signingKey: string | null;
  signingFormat: string | null;
  gpgProgram: string | null;
  gpgSshProgram: string | null;
};

export type GitHubOAuthAppSettings = {
  /** Client ID for the GitHub OAuth application. Set this to use custom (non-GitButler) OAuth application. */
  oauthClientId: string;
};

/** Controls whether GitButler registers reviewed stacks with GitHub's native stacks API. */
export type GitHubStackingMode = "auto" | "disabled" | "native";

export type GithubAccountIdentifier = {
  type: "oAuthUsername";
  info: {
    username: string;
  };
} | {
  type: "patUsername";
  info: {
    username: string;
  };
} | {
  type: "enterprise";
  info: {
    username: string;
    host: string;
  };
};

/**
 * Serializable version of [`AuthStatusResponse`], without the access token.
 *
 * The credential is stored by the backend as part of the call, so the caller is told
 * who authenticated and nothing more. Field names are camelCase for JSON.
 */
export type GithubAuthStatusResponse = {
  login: string;
  name: string | null;
  email: string | null;
  /** The enterprise or self-hosted host, when there is one. */
  host: string | null;
};

/**
 * Serializable version of [`AuthenticatedUser`] with exposed access token.
 *
 * This struct represents an authenticated GitHub user with their credentials
 * exposed as plain strings for API responses. Field names are converted to camelCase for JSON.
 */
export type GithubAuthenticatedUserSensitive = {
  /** The GitHub access token as a plain string (sensitive data). */
  accessToken: string;
  /** The GitHub username/login. */
  login: string;
  /** The URL to the user's avatar image, if available. */
  avatarUrl: string | null;
  /** The user's display name, if available. */
  name: string | null;
  /** The user's email address, if available. */
  email: string | null;
};

export type GitlabAccountIdentifier = {
  type: "patUsername";
  info: {
    username: string;
  };
} | {
  type: "selfHosted";
  info: {
    username: string;
    host: string;
  };
};

/**
 * Serializable version of [`AuthStatusResponse`], without the access token.
 *
 * The credential is stored by the backend as part of the call, so the caller is told
 * who authenticated and nothing more. Field names are camelCase for JSON.
 */
export type GitlabAuthStatusResponse = {
  username: string;
  name: string | null;
  email: string | null;
  /** The enterprise or self-hosted host, when there is one. */
  host: string | null;
};

/**
 * Serializable version of [`AuthenticatedUser`] with exposed access token.
 *
 * This struct represents an authenticated GitLab user with their credentials
 * exposed as plain strings for API responses. Field names are converted to camelCase for JSON.
 */
export type GitlabAuthenticatedUserSensitive = {
  /** The GitLab access token as a plain string (sensitive data). */
  accessToken: string;
  /** The GitLab username. */
  username: string;
  /** The URL to the user's avatar image, if available. */
  avatarUrl: string | null;
  /** The user's display name, if available. */
  name: string | null;
  /** The user's email address, if available. */
  email: string | null;
};

export type GixTime = {
  seconds: number;
  offset: number;
};

export type HeadAndMode = {
  head: string | null;
  operatingMode: OperatingMode;
};

export type HeadSha = {
  headSha: string;
};

/**
 * A type that deserializes a hexadecimal hash into a string, unchanged.
 * This is to workaround `schemars` which doesn't (always) work with transformations.
 */
export type HexHashString = string;

export type HunkAssignment = {
  /**
   * A stable identifier for the hunk assignment.
   *   - When a new hunk is first observed (from the uncommitted changes), it is assigned a new id.
   *   - If a hunk is modified (i.e. it has gained or lost lines), the UUID remains the same.
   *   - If two or more hunks become merged (due to edits causing the contexts to overlap), the id of the hunk with the most lines is adopted.
   */
  id: string | null;
  /**
   * The hunk that is being assigned. Together with path_bytes, this identifies the hunk.
   * If the file is binary, or too large to load, this will be None and in this case the path name is the only identity.
   */
  hunkHeader: HunkHeader | null;
  /** The file path of the hunk. */
  path: string;
  /** The file path of the hunk in bytes. */
  pathBytes: Array<number>;
  /**
   * The stack to which the hunk is assigned, derived from `branch_ref_bytes`
   * through workspace projection.
   */
  stackId: string | null;
  /**
   * The assigned branch as a full ref name (e.g. `refs/heads/my-branch`).
   * This is the source of truth for assignment targeting.
   */
  branchRefBytes: Array<number> | null;
  /** The line numbers that were added in this hunk. */
  lineNumsAdded: Array<number> | null;
  /** The line numbers that were removed in this hunk. */
  lineNumsRemoved: Array<number> | null;
};

/**
 * A request to update a hunk assignment.
 * If a file has multiple hunks, the UI client should send a list of assignment
 * requests with the appropriate hunk headers.
 */
export type HunkAssignmentRequest = {
  /**
   * The hunk that is being assigned. Together with path_bytes, this identifies the hunk.
   * If the file is binary, or too large to load, this will be None and in this case the path name is the only identity.
   * If the file has hunk headers, then header info MUST be provided.
   */
  hunkHeader: HunkHeader | null;
  /** The file path of the hunk in bytes. */
  pathBytes: Array<number>;
  /** Where to assign this hunk. `None` means "unassigned". */
  target: HunkAssignmentTarget | null;
};

/** The target for a hunk assignment request. */
export type HunkAssignmentTarget = {
  type: "stack";
  subject: {
    stackId: string;
  };
} | {
  type: "branch";
  subject: {
    branchRefBytes: Array<number>;
  };
};

/**
 * A way to represent all hunk dependencies that would make it possible to know what can be applied, and were.
 *
 * Note that the [`errors`](Self::errors) field may contain information about specific failures, while other paths
 * may have succeeded computing.
 */
export type HunkDependencies = {
  /** A map from hunk diffs to stack and commit dependencies. */
  diffs: Array<[string, DiffHunk, Array<HunkLock>]>;
  /** Errors that occurred during the calculation that should be presented in some way. */
  errors: Array<CalculationError>;
};

/** The header of a hunk that represents a change to a file. */
export type HunkHeader = {
  /** The 1-based line number at which the previous version of the file started. */
  oldStart: number;
  /** The non-zero number of lines included in the previous version of the file. */
  oldLines: number;
  /** The 1-based line number at which the new version of the file started. */
  newStart: number;
  /** The non-zero number of lines included in the new version of the file. */
  newLines: number;
};

/**
 * A commit that owns this lock, along with the stack that owns it.
 * A hunk is locked when it depends on changes in commits that are in your workspace. A hunk can
 * be locked to more than one branch if it overlaps with more than one committed hunk.
 */
export type HunkLock = {
  /**
   * The ID if available of the stack that contains
   * [`commit_id`](Self::commit_id).
   */
  target: HunkLockTarget;
  /** The commit the hunk applies to. */
  commitId: string;
};

/**
 * The target of a hunk lock. If a stack is identifiable, then it's StackId
 * will be provided.
 */
export type HunkLockTarget = {
  type: "stack";
  subject: string;
} | {
  type: "unidentified";
};

/** How to resolve a single conflict hunk. */
export type HunkResolution = {
  type: "ours";
} | {
  type: "theirs";
} | {
  type: "content";
  subject: string;
} | {
  type: "ai";
};

/** JSON transport type for the outcome of applying per-hunk resolutions. */
export type HunkResolutionResult = {
  /** The conflicted commit the resolutions were applied to. */
  commitId: string;
  /** The rewritten commit. Still conflicted when `remaining` is non-empty. */
  newCommit: string;
  /** How many conflicts were resolved. */
  resolved: number;
  /**
   * Whether the fully resolved commit ended up with the same tree as
   * its parent — the resolutions dropped all of its changes.
   */
  commitEmptied: boolean;
  /** The conflicts that remain, per file. */
  remaining: Array<RemainingConflicts>;
  /** Conflicted files that need manual resolution in edit mode. */
  manual: Array<ManualConflict>;
  /** Workspace state after the apply. */
  workspace: WorkspaceState;
};

/** A way to indicate that a path in the index isn't suitable for committing and needs to be dealt with. */
export type IgnoredWorktreeChange = {
  /** The worktree-relative path to the change. */
  path: string;
  /** The status that caused this change to be ignored. */
  status: IgnoredWorktreeTreeChangeStatus;
};

/** The status we can't handle, which always originated in the worktree. */
export type IgnoredWorktreeTreeChangeStatus = "Conflict" | "TreeIndex" | "TreeIndexWorktreeChangeIneffective";

/** JSON transport type for the initial branch integration proposal. */
export type InitialBranchIntegration = {
  /** The editable execution plan for integrating the branch upstream. */
  integration: InteractiveIntegration;
  /** The current divergence between local branch and upstream for display. */
  divergence: IntegrationDivergenceDisplay;
};

/** Describes where relative to the selector a step should be inserted */
export type InsertSide = "above" | "below";

/** JSON transport type for integrating a branch. */
export type IntegrateBranchResult = {
  /** Workspace state after applying or previewing the integration. */
  workspace: WorkspaceState;
};

/** JSON transport type for a divergence commit row. */
export type IntegrationDivergenceCommit = {
  /** The commit shown in the graph row. */
  id: HexHashString;
  /** The first-line subject shown for the commit. */
  subject: string;
  /** The explicit GitButler Change-Id stored in the commit headers, if present. */
  changeId: string | null;
  /** Commit creation time in Epoch milliseconds. */
  createdAt: number;
  /** The author of the commit. */
  author: Author;
  /** Human-facing ref labels rendered inline on the commit row. */
  refs: Array<string>;
  /** How this commit relates to the configured target branch. */
  targetRelation: IntegrationDivergenceTargetRelation;
};

/** JSON transport type for current branch/upstream divergence information. */
export type IntegrationDivergenceDisplay = {
  /** The local branch being integrated. */
  branchRefName: FullRefName;
  /** The upstream branch this local branch integrates with. */
  upstreamRefName: FullRefName;
  /** Commits only reachable from the local branch tip down to the shared section. */
  localOnly: Array<IntegrationDivergenceCommit>;
  /** Commits only reachable from the upstream branch tip down to the shared section. */
  upstreamOnly: Array<IntegrationDivergenceCommit>;
  /** The merge-base row shown once at the bottom. */
  mergeBase: IntegrationDivergenceCommit;
};

/** JSON transport type for a divergence commit row. */
export type IntegrationDivergenceTargetRelation = {
  kind: "notIntegrated";
} | {
  /** The target branch commit that establishes the relation. */
  targetCommitId: HexHashString;
  kind: "historicallyIntegrated";
};

/** JSON transport type describing an interactive branch integration plan. */
export type InteractiveIntegration = {
  /** Merge base between the upstream and the local reference. */
  mergeBase: HexHashString;
  /** The first parent-to-child local commit that is not historically integrated into target. */
  firstLocalNotIntegrated: HexHashString | null;
  /** The ordered integration steps to apply. */
  steps: Array<InteractiveIntegrationStep>;
};

/** JSON transport type for a branch integration step. */
export type InteractiveIntegrationStep = {
  /** The local commit to keep in the rewritten branch. */
  commitId: HexHashString;
  kind: "pick";
} | {
  /** The ordered commits to squash together. */
  commits: Array<HexHashString>;
  /** Optional replacement message for the squash commit. */
  message: string | null;
  kind: "squash";
} | {
  /** The commit whose change range should be merged. */
  commitId: HexHashString;
  kind: "merge";
};

/** Line statistics obtained from diffing the blobs of one or more [TreeChange](crate::TreeChange). */
export type LineStats = {
  /** The total amount of lines added in the between blobs of the two trees. */
  linesAdded: number;
  /** The total amount of lines removed in the between blobs of the two trees. */
  linesRemoved: number;
  /** The number of files that contributed to these statistics as they were added, removed or modified. */
  filesChanged: number;
};

/** Bit flags for one column in a detailed graph linking row. */
export type LinkLine = number;

/**
 * JSON transport type for a single listed branch, unifying its local ref and all
 * remote-tracking refs of the same name.
 */
export type ListedBranch = {
  /**
   * The full name of the primary ref: the local branch if it exists,
   * otherwise the first remote-tracking branch.
   */
  refName: FullRefName;
  /** The branch name without ref prefix or remote name, for display. */
  displayName: string;
  /** The commit at the tip of the primary ref. */
  tip: HexHashString;
  /** Whether a local branch of this name exists. */
  hasLocal: boolean;
  /** All remote-tracking refs that share the branch name. */
  remoteRefs: Array<FullRefName>;
  /**
   * The number of commits this branch adds on its own — from its tip down to
   * the next listed branch below it in the stack, or to the fork point when
   * it stands alone. This is the count to show as the branch's own commits.
   *
   * A per-branch commit history that is not stack-aware (such as the one
   * from `branchDetails`) lists every commit down to the target, so a stacked
   * branch's own commits are the first `commitCount` of it. For the same
   * reason `commitCount` is smaller than `commitsAheadOfTarget`, which also
   * counts the commits of the branches below.
   *
   * `null` if the commit graph ends before the fork point, as in a shallow
   * clone; an exact-looking number would be wrong.
   */
  commitCount: number | null;
  /**
   * The number of commits reachable from this branch but not from the target
   * branch. For a branch stacked on top of others this includes the commits
   * of those lower branches, so it measures the branch's distance from the
   * target rather than its own contribution — use `commitCount` for that.
   *
   * `null` when no target is configured, or when the connection to the
   * target lies beyond the end of the traversed graph, as in a shallow clone.
   */
  commitsAheadOfTarget: number | null;
  /** The author of the tip commit. */
  lastAuthor: Author | null;
  /** The committer timestamp of the tip commit in milliseconds since the epoch. */
  updatedAtMs: number | null;
  /** The cached review (PR/MR) published for this branch, if any is known. */
  review: ListedForgeReview | null;
  /**
   * The lifecycle state of `review`, derived server-side so every client
   * agrees on the precedence: merged wins over closed, closed over draft,
   * draft over open. `null` exactly when `review` is `null`.
   */
  reviewStatus: BranchReviewStatus | null;
};

/**
 * JSON transport type for the cached review (PR/MR) of a listed branch.
 *
 * Only what a branch listing displays. The full review is available from the
 * per-review APIs; carrying it here would put every review body in a response
 * that lists the whole repository. Lifecycle state lives in `reviewStatus`
 * rather than being re-derived from timestamps.
 */
export type ListedForgeReview = {
  /** The number identifying the review within its repository, e.g. `123`. */
  number: number;
  /** The title of the review. */
  title: string;
  /** The URL to view the review in a web browser. */
  htmlUrl: string;
  /**
   * The forge's symbol for this review type, e.g. `#` for GitHub pull
   * requests and `!` for GitLab merge requests. Precedes `number` when
   * displayed.
   */
  unitSymbol: string;
  /** Labels used to categorize the review. */
  labels: Array<ForgeReviewLabel>;
  /** The review author, which may differ from the latest commit author. */
  author: ListedForgeReviewAuthor | null;
  /** ISO 8601 timestamp of when the review was opened. */
  createdAt: string | null;
};

/** Author identity used to display and search listed reviews. */
export type ListedForgeReviewAuthor = {
  /** The author's username on the forge. */
  login: string;
  /** The author's display name, if available. */
  name: string | null;
};

/**
 * JSON transport type for one or more stacked branches displayed as a unit.
 *
 * A branch belongs to exactly one stack, so the tip branch's `refName`
 * uniquely identifies the stack.
 */
export type ListedStack = {
  /** How the stack relates to the workspace. */
  status: ListedStackStatus;
  /**
   * The branches of the stack, from the tip (newest) to the base (oldest).
   *
   * When flattening branches across stacks, carry `status` along: facts like
   * "this is the target branch" exist only at the stack level.
   */
  branches: Array<ListedBranch>;
  /** The committer timestamp of the newest branch tip in milliseconds since the epoch. */
  updatedAtMs: number | null;
};

/** JSON transport type for how a branch stack relates to the workspace. */
export type ListedStackStatus = "applied" | "unapplied" | "target" | "standalone";

/** A linked worktree as listed by [`worktrees_list()`]. */
export type ListedWorktree = {
  /** The stable worktree name, i.e. the directory name under `$GIT_COMMON_DIR/worktrees/`. */
  name: string;
  /** The worktree checkout directory. */
  path: string;
  /** The branch the worktree has checked out, or `None` for a detached `HEAD`. */
  refName: string | null;
  /**
   * When the worktree or its branch was last updated according to their reflogs, in
   * milliseconds since the epoch, or `None` without any reflog.
   */
  updatedAtMs: number | null;
};

/** Response from `POST /api/login/token.json`. */
export type LoginToken = {
  /**
   * Polling token returned by the API for completing login.
   *
   * This value is sensitive. Although it is obtained via a server-side HTTP
   * call, this struct may be returned from backend commands to browser-based
   * frontends, so callers must avoid exposing or logging it unnecessarily.
   */
  token: string;
  /** Token shown to the user after authentication on gitbutler.com. */
  browser_token: string;
  /** Expiration timestamp. */
  expires: string;
  /** The full URL to redirect the user's browser to for login. */
  url: string;
};

/**
 * A conflicted file with no hunk representation — a side deletion or rename, a
 * non-blob entry, a binary, or one too large to splice — which therefore needs
 * manual resolution in edit mode.
 */
export type ManualConflict = {
  /** The repo-relative path of the file. */
  path: string;
  /** Why it cannot be resolved automatically, for display to the user. */
  reason: string;
};

/**
 * An optional full reference name accepted as a string like `refs/heads/main`,
 * for use as a parameter transport via `#[but_api(...)]`.
 *
 * The name is validated during deserialization. Note that it is lossy: a name
 * that can't be represented in Unicode can't be passed through this type.
 */
export type MaybeLossyFullNameRef = string | null;

/** How to combine messages of commits being squashed. */
export type MessageCombinationStrategy = "KeepBoth" | "KeepSubject" | "KeepTarget";

/**
 * Basic information to know about a reference we store with the metadata system.
 *
 * It allows keeping track of when it changed, but also if we created it initially, a useful
 * bit of information.
 */
export type MetadataRefInfo = {
  /** The time of creation, *if we created the reference*. */
  createdAt: GixTime | null;
  /** The time at which the reference was last modified if we modified it. */
  updatedAt: GixTime | null;
};

export type ModeFlags = "ExecutableBitAdded" | "ExecutableBitRemoved" | "TypeChangeFileToLink" | "TypeChangeLinkToFile" | "TypeChange";

/** JSON transport type for moving a branch. */
export type MoveBranchResult = {
  /** Workspace state after moving or tearing off a branch. */
  workspace: WorkspaceState;
};

/** JSON transport type for moving changes between commits. */
export type MoveChangesResult = {
  /** Workspace state after moving changes. */
  workspace: WorkspaceState;
};

/** Everything needed to create a new comment. See [`DiffComment`] for the field semantics. */
export type NewComment = {
  /** An optional client-supplied ID. An ID will be generated if this is absent. */
  id: string | null;
  /** The worktree-relative path of the file to anchor the comment to. */
  path: string;
  /**
   * `None` to anchor to the uncommitted worktree diff, or the change-id of a workspace commit
   * to anchor to that commit's first-parent diff.
   */
  commitChangeId: string | null;
  /** The side of the diff the anchored line lives on. */
  side: DiffSide;
  /** The 1-based line number of the line to anchor to, in `side`'s coordinates. */
  lineNumber: number;
  /** The comment text. */
  payload: string;
};

/** A linked worktree freshly created by [`worktree_new()`] or [`worktree_new_on_branch_with_perm()`]. */
export type NewWorktree = {
  /** The stable worktree name, i.e. the directory name under `$GIT_COMMON_DIR/worktrees/`. */
  name: string;
  /** The worktree checkout directory. */
  path: string;
  /** The branch checked out in the worktree. */
  refName: string;
  /** The commit the worktree starts at. */
  base: string;
};

/** A column in a detailed graph node row. */
export type NodeLine = "blank" | "ancestor" | "parent" | "node";

export type OperatingMode = {
  type: "OpenWorkspace";
} | {
  type: "OutsideWorkspace";
  subject: OutsideWorkspaceMetadata;
} | {
  type: "Edit";
  subject: EditModeMetadata;
};

export type OperationKind = "CreateCommit" | "CreateBranch" | "StashIntoBranch" | "SetBaseBranch" | "MergeUpstream" | "MergeBranch" | "UpdateWorkspaceBase" | "MoveHunk" | "UpdateBranchName" | "UpdateBranchNotes" | "ReorderBranches" | "UpdateBranchRemoteName" | "GenericBranchUpdate" | "DeleteBranch" | "ApplyBranch" | "SwitchBranch" | "SwitchToWorkspace" | "DiscardLines" | "DiscardHunk" | "DiscardFile" | "DiscardChanges" | "Discard" | "AmendCommit" | "Absorb" | "AutoCommit" | "UndoCommit" | "DiscardCommit" | "UnapplyBranch" | "CherryPick" | "SquashCommit" | "UpdateCommitMessage" | "MoveCommit" | "MoveBranch" | "TearOffBranch" | "ReorderCommit" | "InsertBlankCommit" | "MoveCommitFile" | "FileChanges" | "EnterEditMode" | "ResolveConflicts" | "ResolveConflictsAi" | "SyncWorkspace" | "CreateDependentBranch" | "RemoveDependentBranch" | "UpdateDependentBranchName" | "UpdateDependentBranchDescription" | "UpdateDependentBranchPrNumber" | "AutoHandleChangesBefore" | "AutoHandleChangesAfter" | "SplitBranch" | "CleanWorkspace" | "OnDemandSnapshot" | "Unknown" | "RestoreFromSnapshotViaUndo" | "RestoreFromSnapshotViaRedo" | "RestoreFromSnapshot";

/** What kind of apply operation completed. */
export type OutcomeStatus = "alreadyApplied" | "applied" | "conflictAborted";

export type OutsideWorkspaceMetadata = {
  /** The name of the currently checked out branch or None if in detached head state. */
  branchName: string | null;
  /** The paths of any files that would conflict with the workspace as it currently is */
  worktreeConflicts: Array<string>;
};

/** A column in a detailed graph padding row. */
export type PadLine = "blank" | "ancestor" | "parent";

/**
 * API-specific project type that can be enriched with computed/derived data
 * while preserving the original project structure for persistence.
 *
 * Not registered for ts types because it is only consumed while flattened
 */
export type ProjectForFrontend = {
  id: string;
  title: string;
  description: string | null;
  /** The worktree directory of the project's repository. */
  path: string;
  /**
   * The storage location of the Git repository itself.
   * This is the only value we need to access everything related to the Git repository.
   */
  git_dir?: string;
  /**
   * if ok_with_force_push is true, we'll not try to avoid force pushing
   * for example, when updating base branch
   */
  ok_with_force_push?: boolean;
  /** Force push protection uses safer force push flags instead of doing straight force pushes */
  force_push_protection?: boolean;
  /**
   * Enables running Husky hooks from `../.husky`.
   * Does not affect hooks in `.git/hooks`.
   */
  husky_hooks_enabled?: boolean;
  api: ApiProject | null;
  omit_certificate_check: boolean | null;
  snapshot_lines_threshold: number | null;
  forge_override: string | null;
  preferred_forge_user: ForgeUser | null;
  /** Gerrit mode enabled for this project, derived from git configuration */
  gerrit_mode?: boolean;
  /** Path to the forge review template, if set in git configuration. */
  forge_review_template_path: string | null;
  /** Tell if the project is known to be open in a Window in the frontend. */
  is_open: boolean;
};

/**
 * JSON input for `project_id` parameters.
 *
 * This accepts a [`ProjectHandle`] in all builds, and also accepts a legacy [`LegacyProjectId`]
 * when the `legacy` feature is enabled.
 *
 * Its serialized form is a plain string — see the `Serialize`/`Deserialize` impls below —
 * so it describes itself to schemars as one, and API consumers pass an ordinary string.
 */
export type ProjectHandleOrLegacyProjectId = string;

/**
 * The stored project fields a settings UI can change. An absent field is left alone.
 *
 * A transport DTO rather than [`gitbutler_project::UpdateRequest`], which reaches into
 * `ApiProject`, `FetchResult` and `ForgeUser` and carries fetch bookkeeping no settings
 * screen should be able to write.
 */
export type ProjectSettingsUpdate = {
  title: string | null;
  description: string | null;
  forcePushProtection: boolean | null;
  omitCertificateCheck: boolean | null;
};

/**
 * Parameters for creating a review through the public API.
 *
 * `local_branch` identifies the workspace ref whose reviewed stack determines the target branch.
 * `source_branch` is the possibly-different remote head sent to the forge.
 */
export type PublishReviewInput = {
  title: string;
  body: string;
  localBranch: string;
  sourceBranch: string;
  draft: boolean;
};

/** A newly-created review together with the best-effort stack synchronization result. */
export type PublishReviewOutcome = {
  review: ForgeReview;
  reviewSync: ReviewSyncOutcome;
};

export type PullRequestMinimal = {
  id: number;
  number: number;
  url: string;
  baseRef: string;
  baseRepoUrl: string | null;
  headRef: string;
  headRepoUrl: string | null;
};

export type PushFlag = {
  type: "wip";
} | {
  type: "ready";
} | {
  type: "private";
} | {
  type: "hashtag";
  subject: string;
} | {
  type: "topic";
  subject: string;
};

/** JSON-friendly version of [`gitbutler_git::PushResult`]. */
export type PushResult = {
  /**
   * The name of the remote the push defaulted to.
   *
   * A branch may track a different remote, so read the remote off each entry's
   * refname in `branchToRemote` rather than this one when acting on a branch.
   */
  remote: string;
  /**
   * The list of pushed branches with their remote refnames and the branch name on the remote.
   * Format: (branch_name, remote_refname, remote_branch_name)
   */
  branchToRemote: Array<[string, string, string]>;
  /**
   * The list of branches with their before/after commit SHAs.
   * Format: (branch_name, before_sha, after_sha)
   */
  branchShaUpdates: Array<[string, string, string]>;
  /** Best-effort synchronization of the complete review stack affected by the push. */
  reviewSync: ReviewSyncOutcome;
};

/** Represents the pushable status for the current stack. */
export type PushStatus = "nothingToPush" | "unpushedCommits" | "unpushedCommitsRequiringForce" | "completelyUnpushed" | "integrated";

/**
 * The UI-clone of [`crate::RefInfo`].
 * TODO: should also include base-branch data, see `get_base_branch_data()`.
 */
export type RefInfo = {
  /**
   * The stacks visible in the current workspace.
   *
   * This is an empty array if the `HEAD` is unborn.
   * Otherwise, there is one or more stacks.
   */
  stacks: Array<Stack>;
  /**
   * The target to integrate workspace stacks into.
   *
   * If `None`, this is a local workspace that doesn't know when possibly pushed branches are considered integrated.
   * This happens when there is a local branch checked out without a remote tracking branch.
   */
  target: Target | null;
  /**
   * The active linked worktrees along with the commits they own, or empty if the
   * traversal wasn't seeded with worktree tips.
   */
  worktrees: Array<Worktree>;
};

/** A change that was rejected during commit creation, with the reason for rejection. */
export type RejectedChange = {
  /** The reason the change was rejected. */
  reason: RejectionReason;
  /** The file path of the rejected change, potentially degenerated if it can't be represented in Unicode. */
  path: string;
  /** `path` without degeneration, as plain bytes. */
  pathBytes: Array<number>;
};

/** Provide a description of why a [`crate::DiffSpec`] was rejected for application to the tree of a commit. */
export type RejectionReason = "noEffectiveChanges" | "cherryPickMergeConflict" | "workspaceMergeConflict" | "workspaceMergeConflictOfUnrelatedFile" | "worktreeFileMissingForObjectConversion" | "fileToLargeOrBinary" | "pathNotFoundInBaseTree" | "unsupportedDirectoryEntry" | "unsupportedTreeEntry" | "missingDiffSpecAssociation";

/**
 * Specifies a location, usually used to either have something inserted
 * relative to it, or for the selected object to actually be replaced.
 */
export type RelativeTo = {
  type: "commit";
  subject: string;
} | {
  type: "reference";
  subject: string;
} | {
  type: "referenceBytes";
  subject: Array<number>;
};

/** Conflicts still unresolved in a file after an apply. */
export type RemainingConflicts = {
  /** The repo-relative path of the file. */
  path: string;
  /** How many conflicts remain in it. */
  hunks: number;
};

export type RemoteCommit = {
  id: string;
  description: string;
  authoredAt: number;
  committedAt: number;
  author: Author;
  changeId: string | null;
  parentIds: Array<string>;
  conflicted: boolean;
};

/** A reference in `refs/remotes`. */
export type RemoteTrackingReference = {
  /** The full ref name, like `refs/remotes/origin/on-remote`, for usage with the backend. */
  fullNameBytes: Array<number>;
  /** The short version of `full_name_bytes` for display, like `on-remote`, without the remote name. */
  displayName: string;
  /** The symbolic name of the remote, like `origin`, or `origin/other`. */
  remoteName: string;
};

export type RepoInfo = {
  permissions: RepoPermissions | null;
  fork: boolean;
  /**
   * Whether the repo is visible only to people granted access.
   * `None` when the forge does not report it — Azure, or a GitLab token
   * without the scope to read project metadata.
   */
  private: boolean | null;
  /**
   * Whether the repo deletes the source branch after a PR is merged
   * (GitHub's per-repo "Automatically delete head branches" setting).
   * `None` when the field wasn't returned by the forge.
   */
  deleteBranchOnMerge: boolean | null;
};

export type RepoPermissions = {
  admin: boolean;
  maintain: boolean;
  push: boolean;
  triage: boolean;
  pull: boolean;
};

/**
 * One conflict to resolve, addressed by path and 1-based hunk index as
 * returned by `commit_conflicts()`.
 */
export type ResolutionSpec = {
  /** The repo-relative path of the conflicted file. */
  path: string;
  /** The 1-based index of the conflict within the file. */
  hunk: number;
  /** How to resolve it. */
  resolution: HunkResolution;
};

/** How one conflicted file was resolved, for display to the user. */
export type ResolvedFile = {
  /** The repo-relative path of the file. */
  path: string;
  /** The content that replaced each conflict block, in file order. */
  hunks: Array<string>;
  /** The model's explanation of its decision for this file. */
  reasoning: string;
};

/** The kind of restore to perform. */
export type RestoreKind = "ExplicitRestoreFromSnapshot" | "RestoreFromSnapshotViaUndo" | "RestoreFromSnapshotViaRedo";

/** Metadata about branches, associated with any Git branch. */
export type Review = {
  /** The number for the PR that was associated with this branch. */
  pullRequest: number | null;
  /** A handle to the review created with the GitButler review system. */
  reviewId: string | null;
};

/**
 * How to merge a review on the forge. GitHub honours all three;
 * other forges fall back to their default merge strategy when the
 * caller asks for `Squash`/`Rebase`.
 */
export type ReviewMergeMethod = "merge" | "squash" | "rebase";

/**
 * Forge-agnostic runtime merge state for a review. Always fetched
 * fresh from the forge; not cached. Used by the UI to render the
 * merge-button hint and comment count without forcing every review
 * consumer to subscribe to those expensive fields.
 */
export type ReviewMergeStatus = {
  /**
   * Forge-reported merge state. GitHub strings: `clean`, `dirty`,
   * `unknown`, `blocked`, `behind`, `unstable`, `has_hooks`,
   * `draft`. GitLab strings: `can_be_merged`, `cannot_be_merged`,
   * `checking`, etc. `None` when the forge hasn't computed it.
   * Used by the UI only to surface a specific reason tooltip.
   */
  mergeableState: string | null;
  commentsCount: number;
  /**
   * Forge-normalized: whether merging is allowed. Drives the merge
   * button without forcing the UI to know per-forge state strings.
   */
  isMergeable: boolean;
};

/** Controls where GitButler puts stack information in review descriptions. */
export type ReviewStackingDescription = "bottom" | "top" | "disabled";

export type ReviewState = "open" | "closed";

/**
 * The best-effort result of synchronizing review descriptions and target branches after a
 * durable operation such as a push or review creation.
 */
export type ReviewSyncOutcome = {
  status: "notNeeded";
} | {
  status: "succeeded";
} | {
  message: string;
  status: "failed";
};

/** Information about the project's review template. */
export type ReviewTemplateInfo = {
  /** The relative path to the review template within the repository. */
  path: string;
  /** The content of the review template. */
  content: string;
};

export type Reviews = {
  /** Whether to auto-fill PR title and description from the first commit when a branch has only one commit. */
  autoFillPrDescriptionFromCommit: boolean;
};

/** Update request for [`crate::app_settings::Reviews`]. */
export type ReviewsUpdate = {
  autoFillPrDescriptionFromCommit?: boolean | null;
};

/** A segment of a commit graph, representing a set of commits exclusively. */
export type Segment = {
  /**
   * It is `None` if this branch is the top-most stack segment and the `ref_name` wasn't pointing to
   * a commit anymore that was reached by our rev-walk.
   * This can happen if the ref is deleted, or if it was advanced by other means.
   * Alternatively, the naming would have been ambiguous.
   * Finally, this is `None` of the original name can be found searching upwards, finding exactly one
   * named segment.
   */
  refName: BranchReference | null;
  /**
   * The name of the remote tracking branch of this segment, if present, i.e. `refs/remotes/origin/main`.
   * Its presence means that a remote is configured and that the stack content
   */
  remoteTrackingRefName: RemoteTrackingReference | null;
  /**
   * The portion of commits that can be reached from the tip of the *branch* downwards, so that they are unique
   * for that stack segment and not included in any other stack or stack segment.
   *
   * The list could be empty for when this is a dedicated empty segment as insertion position of commits.
   */
  commits: Array<Commit>;
  /**
   * Commits that are reachable from the remote-tracking branch associated with this branch,
   * but are not reachable from this branch or duplicated by a commit in it.
   * Note that commits that are also similar to commits in `commits` are pruned, and not present here.
   *
   * Note that remote commits along with their remote tracking branch should always retain a shared history
   * with the local tracking branch. If these diverge, we can represent this in data, but currently there is
   * no derived value to make this visible explicitly.
   */
  commitsOnRemote: Array<UpstreamCommit>;
  /**
   * Read-only metadata with additional information about the branch naming the segment,
   * or `None` if nothing was present.
   */
  metadata: Branch | null;
  /** A derived value to help the UI decide which functions to make available. */
  pushStatus: PushStatus;
  /**
   * This is always the `first()` commit in `commits` of the next stacksegment, or the first commit of
   * the first ancestor segment.
   * It can be imagined as the base upon which the segment is resting, or the connection point to the rest
   * of the commit-graph along the first parent.
   * It is `None` if the stack segment contains the first commit in the history, an orphan without ancestry,
   * or if the history traversal was stopped early.
   */
  base: string | null;
};

/** Schema for `serde_error::Error` which serializes as `{description: string, source?: Error | null}`. */
export type SerdeError = {
  description: string;
  source: any | null;
};

/**
 * A single hunk of an uncommitted change, identified by its `path` and `hunk_header`.
 *
 * Unlike `but_hunk_assignment::HunkAssignment` this carries no assignment state. It is a
 * pure function of the diff, so it needs no database and is meaningful in any checkout.
 */
export type SingleHunk = {
  /**
   * The hunk within `path`.
   *
   * `None` for binary files, files too large to diff, and whole-file changes, where
   * `path` is the only identity.
   */
  hunkHeader: HunkHeader | null;
  /** The worktree-relative path of the file this hunk belongs to. */
  pathBytes: Array<number>;
};

export type Snapshot = {
  commitId: string;
  createdAt: number;
  details: SnapshotDetails | null;
};

export type SnapshotDetails = {
  version: number;
  operation: OperationKind;
  title: string;
  body: string | null;
  trailers: Array<Trailer>;
};

/** The UI-clone of `branch::Stack`. */
export type Stack = {
  /** Otherwise, it is `None`. */
  id: string | null;
  /**
   * If there is an integration branch, we know a base commit shared with the integration branch from
   * which we branched off.
   * Otherwise, it's the merge-base of all stacks in the current workspace.
   * It is `None` if this is a stack derived from a branch without relation to any other branch.
   */
  base: string | null;
  /**
   * The branch-name denoted segments of the stack from its tip to the point of reference, typically a merge-base.
   * This array is never empty.
   */
  segments: Array<Segment>;
};

/**
 * **Temporary type to help transitioning to the optional version of stack-entry** and ultimately, to [`crate::RefInfo`].
 * WARNING: for use by parts in the code that can rely on having a non-optional `stack_id`. The goal is to have none of these.
 */
export type StackEntryNoOpt = {
  /** The ID of the stack. */
  id: string;
  /**
   * The list of the branch information that are part of the stack.
   * The list is never empty.
   * The first entry in the list is always the most recent branch on top the stack.
   */
  heads: Array<StackHeadInfo>;
  /** The tip of the top-most branch, i.e., the most recent commit that would become the parent of new commits of the topmost stack branch. */
  tip: string;
  /** The zero-based index for sorting stacks. */
  order: number | null;
  /** If `true`, then any head in this stack is checked directly so `HEAD` points to it, and this is only ever `true` for a single stack. */
  isCheckedOut: boolean;
};

/** The information about the branch inside a stack */
export type StackHeadInfo = {
  /** The name of the branch. */
  name: string;
  /** The tip of the branch. */
  tip: string;
  /** The associated forge review with this branch, e.g. GitHub PRs or GitLab MRs */
  reviewId: number | null;
  /**
   * If `true`, then this head is checked directly so `HEAD` points to it, and this is only ever `true` for a single head.
   * This is `false` if the worktree is checked out.
   */
  isCheckedOut: boolean;
};

/** Represents a reference to an associated virtual branch */
export type StackReference = {
  /** A non-normalized name of the branch, set by the user */
  givenName: string;
  /** Virtual Branch UUID identifier */
  id: string;
  /** Determines if the virtual branch is applied in the workspace */
  inWorkspace: boolean;
  /**
   * List of branches that are part of the stack
   * Ordered from newest to oldest (the most recent branch is first in the list)
   */
  branches: Array<string>;
  /** Pull Request numbers by branch name associated with the stack */
  pullRequests: Record<string, number>;
};

/** Information about the target reference, the one we want to integrate with. */
export type Target = {
  /** The local or remote-tracking branch to integrate with. */
  refName: TargetReference;
  /** The amount of commits that aren't reachable by any segment in the workspace, they are in its future. */
  commitsAhead: number;
  /** The derived upstream, or `None` when the target has no upstream configuration. */
  upstream: TargetUpstream | null;
  /**
   * Whether a stack, or a worktree with something of its own to rebase onto the target, lacks
   * the stored target commit.
   *
   * Updating only some of them leaves the others so, which means an update has work to do
   * even when the stored cutoff matches the upstream tip.
   */
  hasLanesBehind: boolean;
  /**
   * Whether pull can safely advance the local target to the upstream tip.
   * False for equal, ahead, diverged, missing, or checked-out local targets.
   */
  canFastForwardLocalTarget: boolean;
};

/**
 * A commit on the target branch's first-parent line, its relation to the
 * workspace, and the merged review it landed, if known.
 */
export type TargetCommit = {
  /** The commit itself. */
  commit: UpstreamCommit;
  /** The merged review this commit integrated, if known. */
  review: TargetCommitReview | null;
  /** Whether the commit is already reachable from the workspace. */
  inWorkspace: boolean;
};

/** One bounded page of target commits and the state needed to continue it. */
export type TargetCommitPage = {
  /** The commits in this page, newest first. */
  commits: Array<TargetCommit>;
  /** Whether the relative walk was clipped before its natural bound. */
  hasMore: boolean;
};

/**
 * The merged review a target commit landed.
 *
 * Only what the target-commit listing displays; the full review is
 * available from the per-review APIs. The source branch lets clients match
 * workspace branches to the commit that landed them; it is empty when
 * unknown.
 */
export type TargetCommitReview = {
  /** The number identifying the review within its repository, e.g. `123`. */
  number: number;
  /** The title of the review. */
  title: string;
  /** The URL to view the review in a web browser. */
  htmlUrl: string;
  /**
   * The forge's symbol for this review type, e.g. `#` for GitHub pull
   * requests and `!` for GitLab merge requests. Precedes `number` when
   * displayed.
   */
  unitSymbol: string;
  /** The short name of the branch the review proposed, e.g. `feature-branch`. */
  sourceBranch: string;
  /** Labels attached to the review, when available in the forge cache. */
  labels: Array<ForgeReviewLabel>;
};

/** A local or remote-tracking reference used as the integration target. */
export type TargetReference = {
  /** The full ref name, preserving the local or remote-tracking namespace. */
  fullNameBytes: Array<number>;
  /** The branch name for display, without the remote name. */
  displayName: string;
  /** The remote name for a remote-tracking target, or `None` for a local target. */
  remoteName: string | null;
};

/** The target's configured upstream, distinct from the local target itself. */
export type TargetUpstream = {
  /** The derived tracking ref, retained even when its tip is unavailable. */
  refName: TargetReference;
  /** The locally available upstream tip, or `None` if the ref cannot be resolved. */
  tip: string | null;
  /** Whether the stored cutoff equals the available upstream tip. False if either is absent. */
  cutoffMatchesTip: boolean;
};

export type TelemetrySettings = {
  /** Whether the anonymous metrics are enabled. */
  appMetricsEnabled: boolean;
  /** Whether anonymous error reporting is enabled. */
  appErrorReportingEnabled: boolean;
  /** Distinct ID, if reporting is enabled. */
  appDistinctId: string | null;
  /**
   * Whether settings have been migrated from the legacy Tauri store.
   * This flag is set to true after the one-time migration and prevents repeated migration attempts.
   */
  migratedFromLegacy: boolean;
};

/** Update request for [`crate::app_settings::TelemetrySettings`]. */
export type TelemetryUpdate = {
  appMetricsEnabled?: boolean | null;
  appErrorReportingEnabled?: boolean | null;
};

/** Configuration for a terminal application. */
export type TerminalOption = {
  /** The name of the process/program to run. */
  identifier: string;
  /** Human-readable terminal name shown to users in picker and settings UI. */
  displayName: string;
  /**
   * Operating-system family this option applies to: `macos`, `windows`, or
   * `linux`.
   */
  platform: string;
};

export type Trailer = {
  key: string;
  value: string;
};

export type TreeChange = {
  path: string;
  /** Something silently carried back and forth between the frontend and the backend. */
  pathBytes: Array<number>;
  status: TreeStatus;
};

/** All the changes that were made to the tree, including stats */
export type TreeChanges = {
  /** The changes that were made to the tree. */
  changes: Array<TreeChange>;
  /** The stats of the changes. */
  stats: TreeStats;
};

export type TreeStats = {
  /** The total amount of lines added. */
  linesAdded: number;
  /** The total amount of lines removed. */
  linesRemoved: number;
  /** The number of files added, removed or modified. */
  filesChanged: number;
};

export type TreeStatus = {
  type: "Addition";
  subject: {
    state: ChangeState;
    isUntracked: boolean;
  };
} | {
  type: "Deletion";
  subject: {
    previousState: ChangeState;
  };
} | {
  type: "Modification";
  subject: {
    previousState: ChangeState;
    state: ChangeState;
    flags: ModeFlags | null;
  };
} | {
  type: "Rename";
  subject: {
    previousPath: string;
    /** Something silently carried back and forth between the frontend and the backend. */
    previousPathBytes: Array<number>;
    previousState: ChangeState;
    state: ChangeState;
    flags: ModeFlags | null;
  };
};

export type UiSettings = {
  /** Whether to use the native system title bar. */
  useNativeTitleBar: boolean;
  /**
   * When `true`, app windows are drawn without a drop shadow (macOS only).
   * Set in GitButler `settings.json` as `ui.noShadow`; requires an app restart.
   */
  noShadow: boolean;
  /**
   * Whether the `but` CLI is managed by a package manager.
   * When true, the UI should show a specific message instead of installation options.
   */
  cliIsManagedByPackageManager: boolean;
  /**
   * **LEGACY**: The duration between UI update checks in seconds. If `0`, no update checks will be performed.
   * This setting controls Tauri's built-in update mechanism for the desktop application.
   *
   * **DEPRECATED**: This field is legacy and will be replaced by the top-level `appUpdatesCheckIntervalSec` setting.
   * New code should use `appUpdatesCheckIntervalSec` instead, which will control update checks for both CLI and GUI.
   */
  checkForUpdatesIntervalInSeconds: number;
};

/** Update request for [`crate::app_settings::UiSettings`]. */
export type UiUpdate = {
  useNativeTitleBar?: boolean | null;
  noShadow?: boolean | null;
};

/** A grouped source that could not be uncommitted. */
export type UncommitChangesFailure = {
  /** The commit whose changes failed to uncommit. */
  commitId: string;
  /** All changes requested for this commit. */
  changes: Array<DiffSpec>;
  /** Human-readable failure reason. */
  error: string;
};

/** JSON transport type for uncommitting changes from multiple commits. */
export type UncommitChangesFromCommitsResult = {
  /** Workspace state after uncommitting successful sources. */
  workspace: WorkspaceState;
  /** Sources that could not be uncommitted. */
  failures: Array<UncommitChangesFailure>;
};

/**
 * A source entry for uncommitting changes from a commit.
 *
 * Multiple entries may target the same commit; the backend groups them by
 * commit id before removing the changes.
 */
export type UncommitChangesSource = {
  /** The commit to remove `changes` from. */
  commitId: string;
  /** The changes to remove from the commit. */
  changes: Array<DiffSpec>;
};

/** JSON transport type for uncommitting one or more commits. */
export type UncommitResult = {
  /** The IDs of the commits that were uncommitted. */
  uncommittedIds: Array<string>;
  /** Workspace state after uncommitting. */
  workspace: WorkspaceState;
};

/**
 * A patch in unified diff format to show how a resource changed or now looks like (in case it was newly added),
 * or how it previously looked like in case of a deletion.
 */
export type UnifiedPatch = {
  type: "Binary";
} | {
  type: "TooLarge";
  subject: {
    /** The size of the file on disk that made it too large. */
    sizeInBytes: number;
  };
} | {
  type: "Patch";
  subject: {
    /** All non-overlapping hunks, including their context lines. */
    hunks: Array<DiffHunk>;
    /**
     * If `true`, a binary to text filter (`textconv` in Git config) was used to obtain the `hunks` in the diff.
     * This means hunk-based operations must be disabled.
     */
    isResultOfBinaryToTextConversion: boolean;
    /** The total amount of lines added. */
    linesAdded: number;
    /** The total amount of lines removed. */
    linesRemoved: number;
  };
};

/** Parameters for updating the user profile. */
export type UpdateUserParams = {
  name: string | null;
  website: string | null;
  twitter: string | null;
  bluesky: string | null;
  timezone: string | null;
  location: string | null;
  email_share: boolean | null;
  /** Base64-encoded avatar image bytes. */
  avatar_base64: string | null;
  /** Original filename of the avatar (e.g. "photo.png"). */
  avatar_filename: string | null;
  /**
   * Remove the uploaded avatar, so the picture falls back to the sign-in one or
   * Gravatar. Ignored when a new avatar is sent in the same update.
   */
  remove_avatar: boolean | null;
};

/**
 * Commit that is only at the remote.
 * Unlike the `Commit` struct, there is no knowledge of GitButler concepts like conflicted state etc.
 */
export type UpstreamCommit = {
  /** The OID of the commit. */
  id: string;
  /** The message of the commit. */
  message: string;
  /** Time at which the commit was authored, in Epoch milliseconds. */
  authoredAt: number;
  /** Time at which the commit was committed, in Epoch milliseconds. */
  committedAt: number;
  /** The author of the commit. */
  author: Author;
  /** The GitButler change-id associated with this commit, if available. */
  changeId: string | null;
};

/**
 * The signed-in account, without any credential.
 *
 * `json::UserWithSecretsSensitive` carries the GitButler and GitHub access tokens
 * because desktop calls the GitButler API from its frontend. A client that does not
 * should not be handed long-lived credentials to display a name and a picture.
 */
export type UserProfile = {
  id: number;
  name: string | null;
  login: string | null;
  email: string | null;
  picture: string;
  githubUsername: string | null;
};

export type Verification = {
  user_code: string;
  device_code: string;
};

/** The persisted status of fetches performed through [`workspace_fetch_from_remotes()`]. */
export type WorkspaceFetchStatus = {
  /** When the most recent fetch attempt finished, in milliseconds since the Unix epoch. */
  lastAttemptedMs: number | null;
  /**
   * When the most recent successful fetch finished, in milliseconds since the Unix epoch.
   * Partial successes count; see [`workspace_fetch_from_remotes()`].
   */
  lastSuccessfulMs: number | null;
  /**
   * The per-remote errors produced by the most recent attempt, or `None` if every remote
   * fetched successfully.
   */
  lastError: string | null;
};

/** JSON transport type returned by upstream integration. */
export type WorkspaceIntegrateUpstreamOutcome = {
  /** The post-operation or preview workspace state. */
  workspaceState: WorkspaceState;
  /** The updated default target-commit page, or `None` for a dry run or a failed page read. */
  targetCommits: TargetCommitPage | null;
  /** Dirty worktree paths that would conflict when applied onto the resulting workspace head. */
  worktreeConflicts: Array<string>;
};

/** JSON transport type returned by workspace recreation. */
export type WorkspaceRecreateResult = {
  /** Workspace state after recreation, or the unchanged state for a no-op. */
  workspace: WorkspaceState;
  /** Previously applied stack heads that could not be reapplied due to conflicts. */
  conflictingStacks: Array<BranchReference>;
  /** Whether the repository was already on a managed workspace and nothing was changed. */
  alreadyOnWorkspace: boolean;
};

/** Shared JSON transport type for mutation workspace results. */
export type WorkspaceState = {
  /** Commits that were replaced by the operation. Maps `oldId -> newId`. */
  replacedCommits: Record<string, string>;
  /** The post-operation workspace view presented to the frontend. */
  headInfo: RefInfo;
  /**
   * True if a checkout occurred, and a conflict occurred during that
   * checkout.
   */
  checkoutConflictOccurred: boolean;
};

/** A non-archived linked worktree along with the segments it owns exclusively. */
export type Worktree = {
  /** The stable worktree name, i.e. the directory name under `$GIT_COMMON_DIR/worktrees/`. */
  name: string;
  /** The branch the worktree has checked out, or `None` for a detached `HEAD`. */
  refName: BranchReference | null;
  /** The commit the worktree `HEAD` peels to. */
  head: string;
  /**
   * What the last of [`Self::segments`] is resting on, or `None` if the traversal ran out of
   * graph before reaching the workspace or the target (unrelated history, or a limit was hit).
   */
  base: WorktreeBase | null;
  /**
   * The segments owned by this worktree alone, from its `HEAD` down to (excluding) its base,
   * along the first parent. Never empty; the first is named by `ref_name`, or is anonymous
   * for a detached `HEAD`.
   */
  segments: Array<Segment>;
};

/** What a linked worktree's own commits are resting on. */
export type WorktreeBase = {
  type: "InWorkspace";
  subject: string;
} | {
  type: "Outside";
  subject: string;
};

/** Same as `but_core::ui::WorktreeChanges`, but with the addition of hunk assignments. */
export type WorktreeChanges = {
  /** Changes that could be committed. */
  changes: Array<TreeChange>;
  /** Changes that were in the index that we can't handle. The user can see them and interact with them to clear them out before a commit can be made. */
  ignoredChanges: Array<IgnoredWorktreeChange>;
  /**
   * Filesystem modification times in milliseconds since the Unix epoch, keyed by
   * the same (lossy) path as [`TreeChange::path`]. A path with nothing on disk to
   * stat — a deletion — is absent.
   */
  modificationTimes: Record<string, number>;
  assignments: Array<HunkAssignment>;
  assignmentsError: SerdeError | null;
  dependencies: HunkDependencies | null;
  dependenciesError: SerdeError | null;
};

/**
 * All listable linked worktrees, separated by archived state, each most recently
 * updated first and otherwise by name.
 */
export type WorktreeListing = {
  /** Non-archived worktrees. */
  active: Array<ListedWorktree>;
  /** Archived worktrees, hidden from the workspace but still on disk. */
  archived: Array<ListedWorktree>;
};

